{
  "tasks": [
    {
      "task_id": "T1",
      "title": "统计已完成任务（排除丙项目）的工时总和按项目汇总",
      "business_question": "在只统计已完成任务且不包含丙项目的条件下，各项目的工时总和是多少？",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心业务目标“统计已完成任务的工时总和，按项目汇总，并排除丙项目”。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S1",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0003",
                "operator": "eq",
                "value": "已完成"
              },
              {
                "field": "field_0002",
                "operator": "ne",
                "value": "丙"
              }
            ]
          }
        },
        {
          "step_id": "S2",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "sum",
                "field": "field_0004",
                "alias": "total_work_hours"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
